def f(g, mode='vbelow'):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    Fs={(r,c) for r in range(H) for c,x in enumerate(g[r]) if x==4}
    objs=sorted({r for r,c in Fs})
    rs=objs[0]; rh= objs[-1]-objs[0]+1
    out=[row[:] for row in g]
    if mode=='vbelow':  # vertical flip, flush below
        for i,r in enumerate(reversed(objs)):
            for c in Fs & {(r,c)}:
                rr=rs+rh+i
                out[rr][c]=g[r][c]
    elif mode=='vabove':
        for i,r in enumerate(reversed(objs)):
            for c in Fs & {(r,c)}:
                rr=rs-rh+i
                out[rr][c]=g[r][c]
    elif mode=='hright':  # hflip, flush right
        cc=max(c for r,c in Fs)
        for i,r in enumerate(reversed(objs)):
            for c in Fs & {(r,c)}:
                c2=cc-(c-objs[0])+... 
                out[r][cc-(c-min(c for rr2,c2 in Fs if rr2==r))+rh+?] ...
    elif mode=='hleft':
        pass
    else:
        raise
    for r in range(H):
        for c in range(W):
            if g[r][c]==6: out[r][c]=0
    return out
